,"descricao:INSERT","descricao:SELECT","descricao:UPDATE","empresa_id:INSERT","empresa_id:SELECT","id:SELECT","nome:INSERT","nome:SELECT","nome:UPDATE"]},"optional":false},{"identity":"grant:public.treinamentos.anon","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.treinamentos.authenticated","detail":{"table":["SELECT"],"columns":["carga_horaria:INSERT","carga_horaria:SELECT","carga_horaria:UPDATE","certificado_url:INSERT","certificado_url:SELECT","certificado_url:UPDATE","colaborador_id:INSERT","colaborador_id:SELECT","colaborador_id:UPDATE","created_at:SELECT","data_realizacao:INSERT","data_realizacao:SELECT","data_realizacao:UPDATE","data_vencimento:INSERT","data_vencimento:SELECT","data_vencimento:UPDATE","empresa_id:INSERT","empresa_id:SELECT","id:SELECT","instrutor:INSERT","instrutor:SELECT","instrutor:UPDATE","modalidade:INSERT","modalidade:SELECT","modalidade:UPDATE","status:SELECT","treinamento_tipo_id:INSERT","treinamento_tipo_id:SELECT","treinamento_tipo_id:UPDATE"]},"optional":false},{"identity":"grant:public.vw_dashboard_treinamentos.anon","detail":{"table":[],"columns":[]},"optional":false},{"identity":"grant:public.vw_dashboard_treinamentos.authenticated","detail":{"table":["SELECT"],"columns":["colaborador_id:SELECT","colaborador_nome:SELECT","data_realizacao:SELECT","data_vencimento:SELECT","dias_restantes:SELECT","empresa_id:SELECT","status_calculado:SELECT","treinamento_nome:SELECT"]},"optional":false},{"identity":"schema:engmarq_private","detail":{"auth_usage":true,"anon_create":false,"auth_create":false},"optional":false},{"identity":"storage:objects_rls","detail":{"rls":true,"client_owner_member":false},"optional":false},{"identity":"bucket:documentos","detail":{"mime":["application/pdf","application/msword","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.ms-excel","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","image/jpeg","image/png"],"size":10485760,"public":false},"optional":false},{"identity":"bucket:assinaturas","detail":{"mime":["image/jpeg","image/png"],"size":2097152,"public":false},"optional":true},{"identity":"bucket:logos","detail":{"mime":["image/png","image/jpeg","image/webp"],"size":2097152,"public":false},"optional":false},{"identity":"optional-presence:public.fichas_epi","detail":{"present":true},"optional":true},{"identity":"optional-presence:public.fichas_epi_itens","detail":{"present":true},"optional":true}]'::jsonb)e(identity text,detail jsonb))
 SELECT coalesce(a.identity,e.identity) AS "CHECK",
 CASE WHEN a.identity IS NULL THEN 'ausente' WHEN e.identity IS NULL THEN 'objeto adicional' WHEN a.detail IS DISTINCT FROM e.detail THEN 'contrato divergente' ELSE 'contrato conferido' END AS "RESULTADO",
 CASE WHEN coalesce(a.identity,e.identity) ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))' THEN 'ATENÇÃO'
 WHEN a.detail IS DISTINCT FROM e.detail THEN 'BLOQUEIO' ELSE 'OK' END AS "STATUS"
 FROM actual a FULL JOIN expected e USING(identity) ORDER BY 1;

-- Explicit CNPJ inventory: public business identifier only; no contacts or individual employees.
WITH normalized AS (
 SELECT id,cnpj,CASE WHEN btrim(cnpj) COLLATE "C" ~ '^([0-9A-Za-z]{12}[0-9]{2}|[0-9A-Za-z]{2}\.[0-9A-Za-z]{3}\.[0-9A-Za-z]{3}/[0-9A-Za-z]{4}-[0-9]{2})$'
 THEN translate(btrim(cnpj),'abcdefghijklmnopqrstuvwxyz./-','ABCDEFGHIJKLMNOPQRSTUVWXYZ') END canonical FROM public.empresas
),digits AS (
 SELECT n.*, (SELECT sum((ascii(substr(canonical,j,1))-48)*(ARRAY[5,4,3,2,9,8,7,6,5,4,3,2])[j])%11 FROM generate_series(1,12) j) remainder1,
 (SELECT sum((ascii(substr(canonical,j,1))-48)*(ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2])[j])%11 FROM generate_series(1,13) j) remainder2
 FROM normalized n
),validated AS (
 SELECT *,coalesce(canonical IS NOT NULL AND canonical<>repeat(substr(canonical,1,1),14)
 AND substr(canonical,13,1)=(CASE WHEN remainder1<2 THEN 0 ELSE 11-remainder1 END)::text
 AND substr(canonical,14,1)=(CASE WHEN remainder2<2 THEN 0 ELSE 11-remainder2 END)::text,false) valid FROM digits
)
SELECT id AS empresa_id,cnpj,canonical AS cnpj_canonico,
 CASE WHEN canonical IS NULL THEN 'formato inesperado' WHEN NOT valid THEN 'DV inválido/repetido' ELSE 'válido' END AS "RESULTADO",
 CASE WHEN valid THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS" FROM validated ORDER BY id;
WITH normalized AS (
 SELECT id,cnpj,CASE WHEN btrim(cnpj) COLLATE "C" ~ '^([0-9A-Za-z]{12}[0-9]{2}|[0-9A-Za-z]{2}\.[0-9A-Za-z]{3}\.[0-9A-Za-z]{3}/[0-9A-Za-z]{4}-[0-9]{2})$'
 THEN translate(btrim(cnpj),'abcdefghijklmnopqrstuvwxyz./-','ABCDEFGHIJKLMNOPQRSTUVWXYZ') END canonical FROM public.empresas
),digits AS (
 SELECT n.*, (SELECT sum((ascii(substr(canonical,j,1))-48)*(ARRAY[5,4,3,2,9,8,7,6,5,4,3,2])[j])%11 FROM generate_series(1,12) j) remainder1,
 (SELECT sum((ascii(substr(canonical,j,1))-48)*(ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2])[j])%11 FROM generate_series(1,13) j) remainder2
 FROM normalized n
),validated AS (
 SELECT *,coalesce(canonical IS NOT NULL AND canonical<>repeat(substr(canonical,1,1),14)
 AND substr(canonical,13,1)=(CASE WHEN remainder1<2 THEN 0 ELSE 11-remainder1 END)::text
 AND substr(canonical,14,1)=(CASE WHEN remainder2<2 THEN 0 ELSE 11-remainder2 END)::text,false) valid FROM digits
)
SELECT 'Colisão canônica' AS "CHECK",canonical AS "RESULTADO",'BLOQUEIO' AS "STATUS",array_agg(id ORDER BY id) empresas
FROM validated WHERE canonical IS NOT NULL GROUP BY canonical HAVING count(*)>1;
SELECT e.id AS empresa_id,e.status,count(c.id) FILTER(WHERE c.active) AS colaboradores_ativos,
 count(c.id) AS colaboradores_historicos,'ATENÇÃO' AS "STATUS"
 FROM public.empresas e LEFT JOIN public.colaboradores c ON c.empresa_id=e.id GROUP BY e.id,e.status ORDER BY e.id;
WITH checks(label,n) AS (
 SELECT 'Status empresarial inválido',count(*) FROM public.empresas WHERE status IS NULL OR status NOT IN ('ativa','pendente','suspensa')
 UNION ALL SELECT 'Perfil sem Auth ou empresa',count(*) FROM public.user_profiles p LEFT JOIN auth.users u ON u.id=p.id
 LEFT JOIN public.empresas e ON e.id=p.empresa_id WHERE u.id IS NULL OR e.id IS NULL
 UNION ALL SELECT 'Colaborador sem tenant/catálogo coerente',count(*) FROM public.colaboradores c
 LEFT JOIN public.empresas e ON e.id=c.empresa_id LEFT JOIN public.funcoes f ON f.id=c.funcao_id AND f.empresa_id=c.empresa_id
 LEFT JOIN public.setores s ON s.id=c.setor_id AND s.empresa_id=c.empresa_id
 LEFT JOIN public.ambientes a ON a.id=c.ambiente_id AND a.empresa_id=c.empresa_id
 WHERE e.id IS NULL OR f.id IS NULL OR s.id IS NULL OR (c.ambiente_id IS NOT NULL AND a.id IS NULL)
 UNION ALL SELECT 'Documento vinculado a colaborador de outro tenant',count(*) FROM public.documentos d
 LEFT JOIN public.colaboradores c ON c.id=d.colaborador_id AND c.empresa_id=d.empresa_id WHERE d.colaborador_id IS NOT NULL AND c.id IS NULL
 UNION ALL SELECT 'Treinamento/matriz com vínculo incoerente',count(*) FROM (
 SELECT t.id FROM public.treinamentos t LEFT JOIN public.colaboradores c ON c.id=t.colaborador_id AND c.empresa_id=t.empresa_id WHERE c.id IS NULL
 UNION ALL SELECT m.id FROM public.matriz_treinamentos m LEFT JOIN public.funcoes f ON f.id=m.funcao_id AND f.empresa_id=m.empresa_id WHERE f.id IS NULL) invalid
)
SELECT label AS "CHECK",n::text AS "RESULTADO",CASE WHEN n=0 THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS" FROM checks;
SELECT 'Auditor integral' AS "CHECK",current_user AS "RESULTADO",CASE WHEN
 EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS";
SELECT 'Papéis clientes não privilegiados' AS "CHECK",'sem bypass/superuser/membership privilegiado' AS "RESULTADO",CASE WHEN NOT EXISTS(
 SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated') AND (r.rolsuper OR r.rolbypassrls OR EXISTS(
 SELECT 1 FROM pg_roles elevated WHERE (elevated.rolsuper OR elevated.rolbypassrls) AND pg_has_role(r.oid,elevated.oid,'MEMBER')))) THEN 'OK' ELSE 'BLOQUEIO' END AS "STATUS";
SELECT 'Auth sem perfil (inventário técnico)' AS "CHECK",count(*)::text AS "RESULTADO",'ATENÇÃO' AS "STATUS"
 FROM auth.users u LEFT JOIN public.user_profiles p ON p.id=u.id WHERE p.id IS NULL;
SELECT 'Ledger de migrations: conferir 015–023 separadamente' AS "CHECK",coalesce(to_regclass('supabase_migrations.schema_migrations')::text,'não disponível') AS "RESULTADO",'ATENÇÃO' AS "STATUS";
SELECT 'EPI/assinaturas: bloqueador do rollout público na 025' AS "CHECK",
 'Policies legadas preservadas; 024 não remedia Admin global nem gates operacionais' AS "RESULTADO",'ATENÇÃO' AS "STATUS";
SELECT 'Signup e exposição de schemas: configuração fora do catálogo SQL' AS "CHECK",
 'Confirmar dashboard Auth e engmarq_private não exposto; nenhum bootstrap criado na 024' AS "RESULTADO",'ATENÇÃO' AS "STATUS";
SELECT 'Concessões/limites legados não aprovados para backfill nesta migration' AS "CHECK",
 'Revisão comercial explícita posterior; nenhum legado recebe Free' AS "RESULTADO",'ATENÇÃO' AS "STATUS";
SELECT id,name,public,file_size_limit,allowed_mime_types,'ATENÇÃO' AS "STATUS" FROM storage.buckets ORDER BY id;


SELECT 'Preservação: empresas' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r)-ARRAY['cnpj_canonico','cep','logradouro','numero','complemento','bairro'] ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.empresas r
UNION ALL SELECT 'Preservação: user_profiles' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.user_profiles r
UNION ALL SELECT 'Preservação: colaboradores' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.colaboradores r
UNION ALL SELECT 'Preservação: documentos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.documentos r
UNION ALL SELECT 'Preservação: treinamentos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.treinamentos r
UNION ALL SELECT 'Preservação: funcoes' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.funcoes r
UNION ALL SELECT 'Preservação: setores' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.setores r
UNION ALL SELECT 'Preservação: ambientes' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.ambientes r
UNION ALL SELECT 'Preservação: matriz_treinamentos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.matriz_treinamentos r
UNION ALL SELECT 'Preservação: documento_tipos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.documento_tipos r
UNION ALL SELECT 'Preservação: treinamento_tipos' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.treinamento_tipos r
UNION ALL SELECT 'Preservação: exames_catalogo' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM public.exames_catalogo r
UNION ALL SELECT 'Preservação: storage.objects' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM storage.objects r
UNION ALL SELECT 'Preservação: storage.buckets' AS "CHECK",md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id)::text,'[]')) AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM storage.buckets r;
WITH candidates AS (
 SELECT n.nspname schema_name,c.relname relation_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN ('public','engmarq_private','storage') AND c.relname ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))' AND c.relkind IN ('r','p','m')
 UNION SELECT 'public','fichas_epi' UNION SELECT 'public','fichas_epi_itens'
), resolved AS (
 SELECT *,to_regclass(format('%I.%I',schema_name,relation_name)) relation_oid FROM candidates
)
SELECT 'Preservação: '||CASE WHEN schema_name='public' THEN relation_name ELSE schema_name||'.'||relation_name END AS "CHECK",
 CASE WHEN relation_oid IS NULL THEN 'relation ausente no remoto; módulo EPI/Assinaturas fora do escopo da 024; tratar na 025'
 ELSE (xpath('/table/row/fingerprint/text()',query_to_xml(
 format('SELECT md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text)::text,''[]'')) AS fingerprint FROM %I.%I r',schema_name,relation_name),
 true,false,'')))[1]::text END AS "RESULTADO",'ATENÇÃO' AS "STATUS" FROM resolved ORDER BY 1;
WITH actual AS (WITH relations AS (
 SELECT c.*,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE (n.nspname='public' AND c.relname IN ('empresas','user_profiles','colaboradores','funcoes','setores','ambientes','documentos','documento_tipos','treinamentos','treinamento_tipos','matriz_treinamentos','exames_catalogo','fichas_epi','fichas_epi_itens','vw_dashboard_documentos','vw_dashboard_treinamentos','features','empresa_comercial','empresa_features','empresa_limites','empresa_uso','empresa_diagnostico_sst','auditoria_comercial'))
 OR (n.nspname IN ('public','engmarq_private','storage') AND c.relname ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))')
 OR (n.nspname='engmarq_private' AND c.relname='onboarding_solicitacoes')
),entries AS (
 SELECT 'relation:'||nspname||'.'||relname identity,jsonb_build_object('rls',relrowsecurity,'force',relforcerowsecurity,
 'kind',relkind,'options',reloptions,'owner',pg_get_userbyid(relowner),
 'client_owner_member',pg_has_role('authenticated',relowner,'MEMBER') OR pg_has_role('anon',relowner,'MEMBER')) detail FROM relations
 UNION ALL SELECT 'column:'||c.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),
 'nullable',NOT a.attnotnull,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))
 FROM relations c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
 WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'policy:'||schemaname||'.'||tablename||'.'||policyname,
 jsonb_build_object('permissive',permissive,'roles',roles::text,'command',cmd,'using',qual,'check',with_check)
 FROM pg_policies WHERE (schemaname='public' AND tablename IN ('empresas','user_profiles','colaboradores','funcoes','setores','ambientes','documentos','documento_tipos','treinamentos','treinamento_tipos','matriz_treinamentos','exames_catalogo','fichas_epi','fichas_epi_itens','vw_dashboard_documentos','vw_dashboard_treinamentos','features','empresa_comercial','empresa_features','empresa_limites','empresa_uso','empresa_diagnostico_sst','auditoria_comercial'))
 OR (schemaname IN ('public','engmarq_private','storage') AND tablename ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))')
 OR (schemaname='engmarq_private' AND tablename='onboarding_solicitacoes') OR (schemaname='storage' AND tablename='objects')
 UNION ALL SELECT 'function:'||p.oid::regprocedure::text,jsonb_build_object('hash',md5(replace(p.prosrc,E'\r\n',E'\n')),
 'definer',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'type',p.prorettype::regtype::text,
 'owner',pg_get_userbyid(p.proowner),'client_owner_member',pg_has_role('authenticated',p.proowner,'MEMBER') OR pg_has_role('anon',p.proowner,'MEMBER'),
 'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),
 'service',has_function_privilege('service_role',p.oid,'EXECUTE'))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='engmarq_private'
 OR (n.nspname='public' AND p.proname IN ('get_user_empresa_id','get_user_role','update_documento_status','update_treinamento_status','update_ficha_epi_item_status'))
 OR (n.nspname IN ('public','storage') AND p.proname ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))')
 UNION ALL SELECT 'trigger:'||c.nspname||'.'||c.relname||'.'||t.tgname,
 jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)
 FROM pg_trigger t JOIN relations c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'constraint:'||c.nspname||'.'||c.relname||'.'||k.conname,
 jsonb_build_object('definition',pg_get_constraintdef(k.oid),'validated',k.convalidated)
 FROM pg_constraint k JOIN relations c ON c.oid=k.conrelid
 UNION ALL SELECT 'index:'||schemaname||'.'||indexname,jsonb_build_object('definition',indexdef)
 FROM pg_indexes WHERE (schemaname='public' AND tablename IN ('empresas','user_profiles','colaboradores','funcoes','setores','ambientes','documentos','documento_tipos','treinamentos','treinamento_tipos','matriz_treinamentos','exames_catalogo','fichas_epi','fichas_epi_itens','vw_dashboard_documentos','vw_dashboard_treinamentos','features','empresa_comercial','empresa_features','empresa_limites','empresa_uso','empresa_diagnostico_sst','auditoria_comercial')) OR (schemaname='engmarq_private' AND tablename='onboarding_solicitacoes')
 OR (schemaname IN ('public','engmarq_private','storage') AND tablename ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))')
 UNION ALL SELECT 'view:'||nspname||'.'||relname,jsonb_build_object('definition',pg_get_viewdef(oid)) FROM relations WHERE relkind='v'
 UNION ALL SELECT 'grant:'||c.nspname||'.'||c.relname||'.'||r.role,jsonb_build_object(
 'table',ARRAY(SELECT privilege FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) privilege
 WHERE has_table_privilege(r.role,c.oid,privilege) ORDER BY privilege),
 'columns',ARRAY(SELECT a.attname||':'||privilege FROM pg_attribute a CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','REFERENCES']) privilege
 WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege(r.role,c.oid,a.attname,privilege) ORDER BY 1))
 FROM relations c CROSS JOIN (VALUES('anon'),('authenticated'))r(role)
 UNION ALL SELECT 'schema:engmarq_private',jsonb_build_object('auth_usage',has_schema_privilege('authenticated','engmarq_private','USAGE'),
 'auth_create',has_schema_privilege('authenticated','engmarq_private','CREATE'),'anon_create',has_schema_privilege('anon','engmarq_private','CREATE'))
 UNION ALL SELECT 'storage:objects_rls',jsonb_build_object('rls',relrowsecurity,
 'client_owner_member',pg_has_role('authenticated',relowner,'MEMBER') OR pg_has_role('anon',relowner,'MEMBER'))
 FROM pg_class WHERE oid=to_regclass('storage.objects')
 UNION ALL SELECT 'bucket:'||id,jsonb_build_object('public',public,'size',file_size_limit,'mime',allowed_mime_types)
 FROM storage.buckets WHERE id IN ('documentos','logos','assinaturas')
 UNION ALL SELECT 'optional-presence:'||relation,jsonb_build_object('present',to_regclass(relation) IS NOT NULL)
 FROM (VALUES('public.fichas_epi'),('public.fichas_epi_itens')) optional(relation)
) SELECT identity,detail,identity ~ '(fichas_epi|assinatur|(^|[._:])epi([._:(]|$))' AS optional FROM entries)
SELECT 'Preservação: catálogo opcional EPI/Assinaturas' AS "CHECK",
 md5(coalesce(jsonb_agg(jsonb_build_object('identity',identity,'detail',detail) ORDER BY identity)::text,'[]')) AS "RESULTADO",
 'ATENÇÃO' AS "STATUS" FROM actual WHERE optional;
COMMIT;
